const { z } = require("zod");
function symptom(m) { console.error("FAIL: " + m); process.exit(1); }
function broken(m) { console.error("ERROR: " + m); process.exit(2); }
const s = z.httpUrl();
if (!s.safeParse("https://example.com").success) broken("z.httpUrl() rejected https://example.com");
const bad = ["http:example.com", "https:/www.google.com"];
const accepted = bad.filter((u) => s.safeParse(u).success);
if (accepted.length === bad.length) symptom("z.httpUrl() accepts http:example.com and https:/www.google.com");
if (accepted.length) broken("z.httpUrl() accepted only " + accepted.join(", "));
console.log("OK: z.httpUrl() rejects http:example.com and https:/www.google.com");

